//! 🎭️ Partial actor custody survives every denied turn and the real shared frame allocation failure.
use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[test]
fn partial_actor_capture_retains_real_input_and_null_birth_under_one_finite_stock(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../case.schema.json")).unwrap();for(k,v)in f.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}
 let vectors:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🎭️actor/🔣️.json")).unwrap();
 for vector in vectors["cases"].as_array().unwrap(){
  let source=if let Some(s)=vector["text"].as_str(){s.to_owned()}else{vector["repeat"].as_str().unwrap().repeat(vector["bytes"].as_u64().unwrap()as usize)};
  let source_pointer=source.as_ptr();let s=&f["stock"];let mut remaining=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["work"].as_u64().unwrap();let mut owner=ActorCapture::new();let mut output=None;let mut null_seen=false;let mut backing_null=false;
  for _ in 0..f["maximumTurns"].as_u64().unwrap(){
   if owner.terminal_is_empty()&&output.is_some(){break}let grant=RetainedCloneGrant{maximum_items:remaining.maximum_items.min(1),..remaining};let d=owner.next_demand(&source).unwrap();
   let mut denies=vec![RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}];if d.copy_bytes>0{denies.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant});}if d.capacity_bytes>0{denies.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..grant});}
   for denied in denies{let before=owner.phase();let(turn,heap)=observe(||owner.advance(&source,&mut output,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(owner.phase(),before);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);}
   if owner.phase()=="backing"&&!backing_null{
    let((turn,refused),heap)=observe(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.advance(&source,&mut output,grant)));assert_eq!(refused,1);assert_eq!(turn.work,1);assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(owner.phase(),"backing");assert_eq!(owner.text.capacity(),0);assert!(output.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);fuel-=turn.work;backing_null=true;
   }
   if owner.phase()=="shared"&&!null_seen{
    let ptr=owner.text.as_ptr();let((turn,refused),heap)=observe(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.advance(&source,&mut output,grant)));assert_eq!(refused,1);assert_eq!(turn.work,f["sharedNullWork"].as_u64().unwrap());assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(owner.text.as_ptr(),ptr);assert!(output.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);fuel-=turn.work;null_seen=true;
   }
   let(turn,heap)=observe(||owner.advance(&source,&mut output,grant));fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(!heap.overflowed);remaining.maximum_items-=p.copied_items;remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;
  }
  assert!(null_seen&&backing_null&&owner.terminal_is_empty());let mut output=output.unwrap();let reference:String=serde_json::from_value(serde_json::json!(source)).unwrap();assert_eq!(output.original().unwrap().as_str(),reference);assert_eq!(source.as_ptr(),source_pointer);
  for _ in 0..f["maximumTurns"].as_u64().unwrap(){if output.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:remaining.maximum_items.min(1),..remaining};let(step,heap)=observe(||output.step(grant));let work=output.last_turn_work();fuel=fuel.checked_sub(work).unwrap();let p=step.unwrap().progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(!heap.overflowed);remaining.maximum_items-=p.copied_items;remaining.maximum_copy_bytes-=p.copied_bytes;remaining.maximum_capacity_bytes-=p.retained_capacity_bytes;remaining.maximum_release_bytes-=p.released_bytes;}
  assert!(output.terminal_is_empty());let(_,heap)=observe(||{drop(output);drop(owner)});assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(fuel<s["work"].as_u64().unwrap());
 }
}

#[test]
fn partial_actor_cancellation_preserves_each_paid_frontier_and_releases_only_on_grant(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../case.json")).unwrap();
 for cut in f["cancellationCuts"].as_array().unwrap(){let source="actor🧩\0ü".to_owned();let pointer=source.as_ptr();let stock=&f["stock"];let mut remaining=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut fuel=stock["work"].as_u64().unwrap();let mut owner=ActorCapture::new();let mut output=None;let(mut born,mut released)=(0,0);
  for _ in 0..cut.as_u64().unwrap(){let g=RetainedCloneGrant{maximum_items:remaining.maximum_items.min(1),..remaining};let(turn,heap)=observe(||owner.advance(&source,&mut output,g));fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(g));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;debit(&mut remaining,p);}
  for _ in 0..f["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:remaining.maximum_items.min(1),..remaining};let d=owner.close_demand();let mut denials=vec![RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}];if d.release_bytes>0{denials.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}
   for denied in denials{let before=owner.text.as_ptr();let phase=owner.phase();let(turn,heap)=observe(||owner.close_step(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(owner.text.as_ptr(),before);assert_eq!(owner.phase(),phase);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
   let(turn,heap)=observe(||owner.close_step(g));fuel=fuel.checked_sub(turn.work).unwrap();let p=turn.result.unwrap().progress();assert!(p.fits(g));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;debit(&mut remaining,p);if !owner.terminal_is_empty(){let(turn,heap)=observe(||owner.advance(&source,&mut output,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::WorkLimit);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  }
  assert!(owner.terminal_is_empty());if let Some(output)=output.as_mut(){for _ in 0..f["maximumTurns"].as_u64().unwrap(){if output.terminal_is_empty(){break}let g=RetainedCloneGrant{maximum_items:remaining.maximum_items.min(1),..remaining};let(step,heap)=observe(||output.step(g));fuel=fuel.checked_sub(output.last_turn_work()).unwrap();let p=step.unwrap().progress();assert!(p.fits(g));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;debit(&mut remaining,p);}assert!(output.terminal_is_empty());}assert_eq!(born,released);assert_eq!(source.as_ptr(),pointer);let(_,heap)=observe(||{drop(output);drop(owner)});assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(fuel<=stock["work"].as_u64().unwrap());
 }
}
fn debit(g:&mut RetainedCloneGrant,p:RetainedCloneProgress){g.maximum_items=g.maximum_items.checked_sub(p.copied_items).unwrap();g.maximum_copy_bytes=g.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();g.maximum_capacity_bytes=g.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();g.maximum_release_bytes=g.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();}
